-- 209: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 7.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_209_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_209_guard;
INSERT INTO _migration_209_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_025' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_5' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are smooth finished surfaces lightly abraded only inside an adhesive joint area?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Polish the joint until adhesive remains on the surface instead of wetting it","B. Thin both parts through most of their substance before the adhesive is applied","C. Extend the abrasion beyond the seam so the finish colour becomes uniform","D. Expose a clean keyed surface for bonding while preserving the visible finish elsewhere"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Controlled roughening removes weak finish and increases effective contact within the hidden bond area; excessive depth or spread damages strength and appearance. Therefore the correct answer is D: Expose a clean keyed surface for bonding while preserving the visible finish elsewhere.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_025' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_209_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_026' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_6' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How is a traditional two-needle saddle stitch formed through each prepared hole?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A single needle passes through alternate holes and returns along the edge","B. Each needle uses an independent short thread tied inside the same hole","C. Both ends of one thread pass through each hole from opposite sides","D. One needle carries a loop while a separate bobbin thread locks it beneath the leather"]' AND q.correct_answer IS 'C' AND q.explanation IS 'In saddle stitching, a needle is attached to each end of one continuous thread and the two ends cross through every hole from opposite faces, producing a balanced hand seam. Therefore the correct answer is C: Both ends of one thread pass through each hole from opposite sides.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_026' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_209_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_027' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_6' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is a likely effect of placing stitch holes too close to a leather edge?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The stitch line gains more bearing area because it is nearer the cut face","B. The edge distance no longer matters once contact adhesive is added","C. The seam becomes stronger because the thread can tighten around less leather","D. The narrow remaining margin may tear out under seam load"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Thread transfers load through the leather outside each perforation, so the seam needs enough sound edge margin to resist the concentrated force without splitting. Therefore the correct answer is D: The narrow remaining margin may tear out under seam load.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_027' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_209_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_028' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_6' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When should two surfaces coated with contact adhesive normally be joined?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Immediately while both coatings are freely wet so the parts can slide into alignment","B. At a standard fifteen-minute wait for water-based and solvent-based products","C. After the carrier has flashed off and the manufacturer-specified tack time is reached","D. After both films have cured hard and surface tack has disappeared"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Contact adhesives develop their intended grab after the water or solvent carrier has flashed off to the specified tack stage; the product instructions govern open time and reactivation. Therefore the correct answer is C: After the carrier has flashed off and the manufacturer-specified tack time is reached.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_028' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_025', 'topic_was_leatherwork_b004_5', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Why are smooth finished surfaces lightly abraded only inside an adhesive joint area?', 'multiple_choice', NULL, '["A. Polish the joint until adhesive remains on the surface instead of wetting it","B. Thin both parts through most of their substance before the adhesive is applied","C. Extend the abrasion beyond the seam so the finish colour becomes uniform","D. Expose a clean keyed surface for bonding while preserving the visible finish elsewhere"]', 'D', 'Controlled roughening removes weak finish and increases effective contact within the hidden bond area; excessive depth or spread damages strength and appearance. Therefore the correct answer is D: Expose a clean keyed surface for bonding while preserving the visible finish elsewhere.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_5', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_026', 'topic_was_leatherwork_b004_6', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'How is a traditional two-needle saddle stitch formed through each prepared hole?', 'multiple_choice', NULL, '["A. A single needle passes through alternate holes and returns along the edge","B. Each needle uses an independent short thread tied inside the same hole","C. Both ends of one thread pass through each hole from opposite sides","D. One needle carries a loop while a separate bobbin thread locks it beneath the leather"]', 'C', 'In saddle stitching, a needle is attached to each end of one continuous thread and the two ends cross through every hole from opposite faces, producing a balanced hand seam. Therefore the correct answer is C: Both ends of one thread pass through each hole from opposite sides.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_6', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_027', 'topic_was_leatherwork_b004_6', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What is a likely effect of placing stitch holes too close to a leather edge?', 'multiple_choice', NULL, '["A. The stitch line gains more bearing area because it is nearer the cut face","B. The edge distance no longer matters once contact adhesive is added","C. The seam becomes stronger because the thread can tighten around less leather","D. The narrow remaining margin may tear out under seam load"]', 'D', 'Thread transfers load through the leather outside each perforation, so the seam needs enough sound edge margin to resist the concentrated force without splitting. Therefore the correct answer is D: The narrow remaining margin may tear out under seam load.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_6', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_028', 'topic_was_leatherwork_b004_6', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'When should two surfaces coated with contact adhesive normally be joined?', 'multiple_choice', NULL, '["A. Immediately while both coatings are freely wet so the parts can slide into alignment","B. At a standard fifteen-minute wait for water-based and solvent-based products","C. After the carrier has flashed off and the manufacturer-specified tack time is reached","D. After both films have cured hard and surface tack has disappeared"]', 'C', 'Contact adhesives develop their intended grab after the water or solvent carrier has flashed off to the specified tack stage; the product instructions govern open time and reactivation. Therefore the correct answer is C: After the carrier has flashed off and the manufacturer-specified tack time is reached.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_6', 'Identify', 'AO1', NULL, NULL, 'board_waec');
